import{_ as t,g as a,e as d,a4 as o}from"./chunks/framework.CEYJDsBW.js";const u=JSON.parse('{"title":"块标签、布局和公式","description":"","frontmatter":{},"headers":[],"relativePath":"ageratum/26.1/packs/blocks.md","filePath":"ageratum/26.1/packs/blocks.md"}'),r={name:"ageratum/26.1/packs/blocks.md"};function c(n,e,i,s,l,p){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="块标签、布局和公式" tabindex="-1">块标签、布局和公式 <a class="header-anchor" href="#块标签、布局和公式" aria-label="Permalink to &quot;块标签、布局和公式&quot;">​</a></h1><p>提示框和行布局可以嵌套。开闭标签分别独占一行，单个无正文的对象使用自闭合形式。下面的两种材料会在同一行居中显示。</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;tip&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">修理前先准备材料。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/tip&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;row direction=&quot;horizontal&quot; halign=&quot;center&quot; valign=&quot;center&quot;&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;item id=&quot;minecraft:iron_ingot&quot;/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;item id=&quot;minecraft:iron_pickaxe&quot;/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/row&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;latex formula=&quot;a^2+b^2=c^2&quot; dpi=&quot;150&quot; color=&quot;#29405B&quot; center=&quot;true&quot;/&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>标签或参数</th><th>类型</th><th>要求与缺省行为</th></tr></thead><tbody><tr><td><code>info</code>、<code>tip</code>、<code>warning</code>、<code>danger</code></td><td>成对的块标签</td><td>接受解析后的 Markdown 子内容。没有必填属性。</td></tr><tr><td><code>row.direction</code>（别名 <code>dir</code>）</td><td>字符串</td><td>可选，默认 <code>horizontal</code>。垂直排列接受 <code>v</code>、<code>vertical</code>、<code>column</code>、<code>col</code>。</td></tr><tr><td><code>row.halign</code></td><td>字符串</td><td>可选，默认 <code>left</code>。可写 <code>center</code> 或 <code>right</code>，别名按 <code>alignX</code>、<code>xAlign</code>、<code>align</code> 顺序回退。</td></tr><tr><td><code>row.valign</code></td><td>字符串</td><td>可选，默认 <code>top</code>。水平排列时控制行内的 <code>center</code> 或 <code>bottom</code> 对齐，别名 <code>alignY</code>、<code>yAlign</code>。</td></tr><tr><td><code>latex.formula</code></td><td>字符串</td><td>与非空块正文至少提供一项。属性优先。</td></tr><tr><td><code>latex.dpi</code></td><td>整数字符串</td><td>可选，默认 150，限制在 72 至 600。</td></tr><tr><td><code>latex.scale</code></td><td>数值字符串</td><td>可选。缺省解析值为 0.1，实际显示还受最小可读高度、布局空间及 0.5 至 2.0 的缩放限制。</td></tr><tr><td><code>latex.color</code></td><td>十六进制颜色字符串</td><td>可选，默认黑色，接受带或不带 <code>#</code> 的六位颜色。</td></tr><tr><td><code>latex.center</code></td><td>布尔字符串</td><td>可选，默认 <code>true</code>。</td></tr></tbody></table><p>公式组件向 CodeCogs 请求图片。无法连通时会显示加载或失败提示。要在离线整合包中展示固定公式，也可以把公式图片随资源包发布。<a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/component/extend/MDLatexComponent.java" target="_blank" rel="noreferrer">公式组件</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/component/extend/MDRowComponent.java" target="_blank" rel="noreferrer">行布局</a></p><h2 id="参数怎么被读取" tabindex="-1">参数怎么被读取 <a class="header-anchor" href="#参数怎么被读取" aria-label="Permalink to &quot;参数怎么被读取&quot;">​</a></h2><p>标签属性是 <code>key=value</code>。键支持字母、数字、下划线、点号和连字符。值可以无引号，包含空格时应选单引号或双引号。重复键取最后一个值。外层用单引号可以原样包住 JSON 对象内部的双引号。这里使用键值对解析器，组件只在其对应字段中调用 JSON 或 SNBT 解码器。通用 HOCON 对象没有解析入口。</p><p><code>::: tip</code> 加独立结束行 <code>:::</code> 可以写提示框。冒号语法把尾部作为原始参数传给工厂。内置 <code>row</code> 会另外解析这段文本。需要 <code>id</code> 等结构化属性的内置组件宜使用标签语法。<a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/ExtensionParamParser.java" target="_blank" rel="noreferrer">属性解析器</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/MarkdownParser.java" target="_blank" rel="noreferrer">块解析器</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/registries/BuiltinExtensionComponents.java" target="_blank" rel="noreferrer">工厂登记表</a></p>`,8)])])}const g=t(r,[["render",c]]);export{u as __pageData,g as default};
